<?php
$q=trim((string)($_GET['q']??''));$pageNo=max(1,(int)($_GET['p']??1));$perPage=10;
$where=$q!==''?'WHERE k.nama_kategori LIKE ?':'';$args=$q!==''?["%$q%"]:[];
$count=$db->prepare("SELECT COUNT(*) FROM tbl_kategori k {$where}");$count->execute($args);$total=(int)$count->fetchColumn();$offset=($pageNo-1)*$perPage;
$stmt=$db->prepare("SELECT k.*,COUNT(p.id_produk) jumlah_produk FROM tbl_kategori k LEFT JOIN tbl_produk p ON p.id_kategori=k.id_kategori {$where} GROUP BY k.id_kategori ORDER BY k.nama_kategori LIMIT {$perPage} OFFSET {$offset}");$stmt->execute($args);$rows=$stmt->fetchAll();
?>
<div class="page-heading"><div><span class="section-kicker">PENGELOMPOKAN PRODUK</span><h1>Kategori Produk</h1><p>Kelompokkan barang agar pelanggan dan kasir lebih mudah mencari produk.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#categoryModal"><i class="bi bi-plus-lg me-2"></i>Tambah Kategori</button></div>
<div class="panel-card"><div class="filter-toolbar"><form class="filter-form" method="get"><input type="hidden" name="page" value="categories"><div class="search-box"><i class="bi bi-search"></i><input type="search" name="q" value="<?=e($q)?>" placeholder="Cari kategori..."></div><button class="btn btn-dark-soft">Cari</button></form><span class="result-count"><?=$total?> kategori</span></div>
<div class="table-responsive"><table class="table app-table align-middle"><thead><tr><th>Nama Kategori</th><th>Deskripsi</th><th>Jumlah Produk</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody>
<?php if(!$rows):?><tr><td colspan="5"><div class="empty-state">Belum ada kategori ditemukan.</div></td></tr><?php endif;?>
<?php foreach($rows as $r):?><tr><td><div class="product-cell"><div class="category-avatar"><i class="bi bi-grid-3x3-gap"></i></div><b><?=e($r['nama_kategori'])?></b></div></td><td><?=e($r['deskripsi']?:'-')?></td><td><span class="count-pill"><?=(int)$r['jumlah_produk']?> produk</span></td><td><?=status_badge($r['status_kategori'])?></td><td class="text-end"><div class="table-actions"><button class="btn btn-sm btn-light" data-bs-toggle="modal" data-bs-target="#editCategory<?=(int)$r['id_kategori']?>"><i class="bi bi-pencil"></i></button><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="toggle_category"><input type="hidden" name="_return" value="categories"><input type="hidden" name="id" value="<?=(int)$r['id_kategori']?>"><button class="btn btn-sm btn-light" title="Ubah status"><i class="bi bi-toggle-on"></i></button></form></div></td></tr><?php endforeach;?>
</tbody></table></div><div class="panel-footer"><span class="text-muted small">Halaman <?=$pageNo?></span><?php pagination($total,$pageNo,$perPage,'categories',['q'=>$q]);?></div></div>
<div class="modal fade" id="categoryModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="save_category"><input type="hidden" name="_return" value="categories"><div class="modal-header"><h5 class="modal-title">Tambah Kategori</h5><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><label class="form-label">Nama Kategori *</label><input class="form-control mb-3" name="nama_kategori" required placeholder="Contoh: Makanan & Minuman"><label class="form-label">Deskripsi</label><textarea class="form-control" rows="3" name="deskripsi"></textarea></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div></div></div>
<?php foreach($rows as $r):?><div class="modal fade" id="editCategory<?=(int)$r['id_kategori']?>" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="save_category"><input type="hidden" name="_return" value="categories"><input type="hidden" name="id_kategori" value="<?=(int)$r['id_kategori']?>"><div class="modal-header"><h5 class="modal-title">Edit Kategori</h5><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><label class="form-label">Nama Kategori *</label><input class="form-control mb-3" name="nama_kategori" required value="<?=e($r['nama_kategori'])?>"><label class="form-label">Deskripsi</label><textarea class="form-control" rows="3" name="deskripsi"><?=e($r['deskripsi'])?></textarea></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary">Simpan Perubahan</button></div></form></div></div></div><?php endforeach;?>
